#!/usr/bin/env bash
# setup-git-hooks.sh: the root `prepare` script (runs on every `npm install` in the repo root).
# Installs the husky hooks so that the main checkout and every `git worktree add` checkout run them.
#
# husky alone sets core.hooksPath to `.husky/_`, a relative path that git resolves inside each
# worktree. `.husky/_` is generated by husky and gitignored, so it exists only where husky ran, and
# every linked worktree then runs no hooks at all, without any message. core.hooksPath lives in the
# repository config that all worktrees share, so this script runs husky in the main checkout and
# stores the absolute path of that `.husky/_` instead. The path is written to .git/config only.
#
# Run it through npm (`npm run prepare`), which puts husky on PATH.
set -euo pipefail

# No git repository (for example an install from a source archive): nothing to install.
common_dir="$(git rev-parse --path-format=absolute --git-common-dir 2>/dev/null)" || exit 0
case "$common_dir" in
  */.git) main_checkout="${common_dir%/.git}" ;;
  # Submodule or --separate-git-dir: the main checkout is not the git dir's parent. Plain husky,
  # as before this script: hooks run in this checkout, not in its linked worktrees.
  *) exec husky ;;
esac

cd "$main_checkout"
husky
# husky skips itself with HUSKY=0 and says so; keep that opt-out.
[ "${HUSKY:-}" = "0" ] && exit 0

if [ ! -f .husky/_/h ]; then
  echo "setup-git-hooks: husky did not create $main_checkout/.husky/_; hooks not installed" >&2
  exit 1
fi
git config core.hooksPath "$main_checkout/.husky/_"
echo "setup-git-hooks: core.hooksPath = $main_checkout/.husky/_ (used by every worktree)"
